1	/**
2	 * @module core/data/openMeteo
3	 *
4	 * Client for the Open-Meteo Historical Weather API (archive).
5	 * Docs: https://open-meteo.com/en/docs/historical-weather-api
6	 *
7	 * Data is modeled reanalysis (not station measurements) on a ~9–11 km grid.
8	 * Free tier is non-commercial; attribution (CC BY 4.0) is required.
9	 */
10	import { z } from "zod";
11	import { OPEN_METEO_DAILY_VARIABLES } from "../config/ingestConfig";
12	import type { DailyWeather } from "../domain/weather";
13	import { BoundaryError } from "../errors/boundaryError";
14	import { daysInclusive } from "../utils/dates";
15	import { fetchJsonWithRetry, type FetchLike, type SleepFn } from "./http";
16	
17	const ARCHIVE_URL = "https://archive-api.open-meteo.com/v1/archive";
18	
19	/** What to fetch: one point, one date range. */
20	export interface ArchiveRequest {
21	  latitude: number;
22	  longitude: number;
23	  /** IANA timezone, so "a day" is the hub's local calendar day. */
24	  timezone: string;
25	  startDate: string;
26	  endDate: string;
27	}
28	
29	/** Expected units — if Open-Meteo ever changes them we fail loudly instead of storing wrong numbers. */
30	const EXPECTED_UNITS = {
31	  snowfall_sum: "cm",
32	  temperature_2m_min: "°C",
33	  precipitation_sum: "mm",
34	  wind_gusts_10m_max: "km/h",
35	  apparent_temperature_max: "°C",
36	} as const;
37	
38	const nullableNumbers = z.array(z.number().nullable());
39	
40	/** Shape of the archive response we rely on. */
41	const archiveResponseSchema = z.object({
42	  daily_units: z.object(
43	    Object.fromEntries(OPEN_METEO_DAILY_VARIABLES.map((name) => [name, z.literal(EXPECTED_UNITS[name])])) as {
44	      [K in keyof typeof EXPECTED_UNITS]: z.ZodLiteral<(typeof EXPECTED_UNITS)[K]>;
45	    },
46	  ),
47	  daily: z.object({
48	    time: z.array(z.string()),
49	    snowfall_sum: nullableNumbers,
50	    temperature_2m_min: nullableNumbers,
51	    precipitation_sum: nullableNumbers,
52	    wind_gusts_10m_max: nullableNumbers,
53	    apparent_temperature_max: nullableNumbers,
54	  }),
55	});
56	
57	/**
58	 * Builds the archive request URL.
59	 * @param request - point, timezone and date range.
60	 * @returns the full URL.
61	 */
62	export function buildArchiveUrl(request: ArchiveRequest): string {
63	  const params = new URLSearchParams({
64	    latitude: String(request.latitude),
65	    longitude: String(request.longitude),
66	    start_date: request.startDate,
67	    end_date: request.endDate,
68	    daily: OPEN_METEO_DAILY_VARIABLES.join(","),
69	    timezone: request.timezone,
70	  });
71	  return `${ARCHIVE_URL}?${params.toString()}`;
72	}
73	
74	/**
75	 * Estimates how many "calls" Open-Meteo counts for a request: requests over
76	 * 10 variables or 14 days count as fractional multiples.
77	 * @param days - number of days requested.
78	 * @param variableCount - number of variables requested.
79	 * @returns the weighted call count (at least 1).
80	 */
81	export function estimateCallWeight(days: number, variableCount: number = OPEN_METEO_DAILY_VARIABLES.length): number {
82	  return Math.max(1, variableCount / 10) * Math.max(1, days / 14);
83	}
84	
85	/**
86	 * Validates an archive response and turns it into one object per day.
87	 * Trailing days where every value is null (not published yet) are dropped.
88	 * @param json - the raw response body.
89	 * @returns the days, oldest first.
90	 * @throws ZodError when the shape or units are unexpected.
91	 * @throws Error when the arrays have different lengths.
92	 */
93	export function parseArchiveResponse(json: unknown): DailyWeather[] {
94	  const { daily } = archiveResponseSchema.parse(json);
95	  const length = daily.time.length;
96	  for (const name of OPEN_METEO_DAILY_VARIABLES) {
97	    if (daily[name].length !== length) throw new Error(`Open-Meteo array '${name}' has ${daily[name].length} values, expected ${length}`);
98	  }
99	
100	  const days: DailyWeather[] = daily.time.map((date, i) => ({
101	    date,
102	    snowfallCm: daily.snowfall_sum[i],
103	    tempMinC: daily.temperature_2m_min[i],
104	    precipitationMm: daily.precipitation_sum[i],
105	    windGustMaxKmh: daily.wind_gusts_10m_max[i],
106	    apparentTempMaxC: daily.apparent_temperature_max[i],
107	  }));
108	
109	  let end = days.length;
110	  while (end > 0 && isEmptyDay(days[end - 1])) end--;
111	  return days.slice(0, end);
112	}
113	
114	/** True when a day has no values at all. */
115	function isEmptyDay(day: DailyWeather): boolean {
116	  return (
117	    day.snowfallCm === null &&
118	    day.tempMinC === null &&
119	    day.precipitationMm === null &&
120	    day.windGustMaxKmh === null &&
121	    day.apparentTempMaxC === null
122	  );
123	}
124	
125	/**
126	 * Fetches daily weather for one point and date range.
127	 * @param request - point, timezone and date range.
128	 * @param deps - injectable fetch/sleep for tests.
129	 * @returns validated days, oldest first.
130	 * @throws BoundaryError (openMeteo) on HTTP failure or an unexpected response.
131	 */
132	export async function fetchDailyWeather(
133	  request: ArchiveRequest,
134	  deps: { fetchImpl?: FetchLike; sleepImpl?: SleepFn } = {},
135	): Promise<DailyWeather[]> {
136	  if (daysInclusive(request.startDate, request.endDate) === 0) return [];
137	  const json = await fetchJsonWithRetry({
138	    url: buildArchiveUrl(request),
139	    boundary: "openMeteo",
140	    functionName: "fetchDailyWeather",
141	    errorName: "OpenMeteoFetchError",
142	    ...deps,
143	  });
144	  try {
145	    return parseArchiveResponse(json);
146	  } catch (cause) {
147	    throw new BoundaryError({
148	      name: "OpenMeteoResponseError",
149	      message: `Unexpected archive response for ${request.startDate}..${request.endDate}`,
150	      functionName: "fetchDailyWeather",
151	      boundary: "openMeteo",
152	      cause,
153	    });
154	  }
155	}
