1	/**
2	 * @module core/data/femaNri
3	 *
4	 * Client for the FEMA National Risk Index (NRI) county layer, served by FEMA's
5	 * public ArcGIS feature service (no key needed). We look up the county that
6	 * contains a hub's point and keep each hazard's annualized frequency (AFREQ =
7	 * expected events per year).
8	 *
9	 * Data page: https://hazards.fema.gov/nri/data-resources
10	 */
11	import { z } from "zod";
12	import { BoundaryError } from "../errors/boundaryError";
13	import { fetchJsonWithRetry, type FetchLike, type SleepFn } from "./http";
14	
15	const COUNTY_LAYER_URL =
16	  "https://services.arcgis.com/XG15cJAlne2vxtgt/arcgis/rest/services/National_Risk_Index_Counties/FeatureServer/0/query";
17	
18	/** FEMA hazard codes we use, mapped to our column names. */
19	export const FEMA_HAZARD_FIELDS = {
20	  HRCN_AFREQ: "hrcnAfreq", // hurricane
21	  TRND_AFREQ: "trndAfreq", // tornado
22	  HAIL_AFREQ: "hailAfreq", // hail
23	  IFLD_AFREQ: "ifldAfreq", // inland flooding (formerly RFLD)
24	  CFLD_AFREQ: "cfldAfreq", // coastal flooding
25	  ISTM_AFREQ: "istmAfreq", // ice storm
26	  WNTW_AFREQ: "wntwAfreq", // winter weather
27	  CWAV_AFREQ: "cwavAfreq", // cold wave
28	  HWAV_AFREQ: "hwavAfreq", // heat wave
29	  SWND_AFREQ: "swndAfreq", // strong wind
30	} as const;
31	
32	type FemaFieldName = keyof typeof FEMA_HAZARD_FIELDS;
33	type FemaHazardKey = (typeof FEMA_HAZARD_FIELDS)[FemaFieldName];
34	
35	/** FEMA NRI record for the county containing a hub. `null` frequency = hazard not applicable there. */
36	export type FemaCountyRecord = {
37	  countyFips: string;
38	  countyName: string;
39	  stateCode: string;
40	  nriVersion: string;
41	  /** County area in square miles (FEMA `AREA`). Used to score tornado per area (D53). */
42	  countyAreaSqMi: number;
43	  /** Every attribute FEMA returned, kept for traceability. */
44	  rawAttributes: Record<string, unknown>;
45	} & Record<FemaHazardKey, number | null>;
46	
47	const ID_FIELDS = ["STCOFIPS", "COUNTY", "STATEABBRV", "NRI_VER", "AREA"] as const;
48	
49	const attributesSchema = z
50	  .object({
51	    STCOFIPS: z.string().regex(/^\d{5}$/),
52	    COUNTY: z.string().min(1),
53	    STATEABBRV: z.string().length(2),
54	    NRI_VER: z.string().min(1),
55	    AREA: z.number().positive(),
56	    ...Object.fromEntries(
57	      Object.keys(FEMA_HAZARD_FIELDS).map((field) => [field, z.number().min(0).nullable()]),
58	    ),
59	  })
60	  .loose();
61	
62	const queryResponseSchema = z.object({
63	  features: z.array(z.object({ attributes: z.record(z.string(), z.unknown()) })),
64	});
65	
66	/**
67	 * Builds the "which county contains this point?" query URL.
68	 * @param latitude - point latitude.
69	 * @param longitude - point longitude.
70	 * @returns the query URL.
71	 */
72	export function buildCountyQueryUrl(latitude: number, longitude: number): string {
73	  const params = new URLSearchParams({
74	    geometry: `${longitude},${latitude}`,
75	    geometryType: "esriGeometryPoint",
76	    inSR: "4326",
77	    spatialRel: "esriSpatialRelIntersects",
78	    outFields: [...ID_FIELDS, ...Object.keys(FEMA_HAZARD_FIELDS)].join(","),
79	    returnGeometry: "false",
80	    f: "json",
81	  });
82	  return `${COUNTY_LAYER_URL}?${params.toString()}`;
83	}
84	
85	/**
86	 * Validates the ArcGIS response and extracts the county record.
87	 * @param json - the raw response body.
88	 * @returns the county record.
89	 * @throws Error when no county contains the point (e.g. outside the US).
90	 * @throws ZodError when fields are missing or malformed.
91	 */
92	export function parseCountyResponse(json: unknown): FemaCountyRecord {
93	  const { features } = queryResponseSchema.parse(json);
94	  if (features.length === 0) throw new Error("No FEMA county contains this point");
95	  const raw = features[0].attributes;
96	  const attributes = attributesSchema.parse(raw) as Record<string, unknown>;
97	
98	  const hazards = Object.fromEntries(
99	    (Object.entries(FEMA_HAZARD_FIELDS) as [FemaFieldName, FemaHazardKey][]).map(([field, key]) => [
100	      key,
101	      attributes[field] as number | null,
102	    ]),
103	  ) as Record<FemaHazardKey, number | null>;
104	
105	  return {
106	    countyFips: attributes.STCOFIPS as string,
107	    countyName: attributes.COUNTY as string,
108	    stateCode: attributes.STATEABBRV as string,
109	    nriVersion: attributes.NRI_VER as string,
110	    countyAreaSqMi: attributes.AREA as number,
111	    rawAttributes: raw,
112	    ...hazards,
113	  };
114	}
115	
116	/**
117	 * Fetches the FEMA NRI record for the county containing a point.
118	 * @param latitude - point latitude.
119	 * @param longitude - point longitude.
120	 * @param deps - injectable fetch/sleep for tests.
121	 * @returns the county record.
122	 * @throws BoundaryError (fema) on HTTP failure, no county, or an unexpected response.
123	 */
124	export async function fetchFemaCountyByPoint(
125	  latitude: number,
126	  longitude: number,
127	  deps: { fetchImpl?: FetchLike; sleepImpl?: SleepFn } = {},
128	): Promise<FemaCountyRecord> {
129	  const json = await fetchJsonWithRetry({
130	    url: buildCountyQueryUrl(latitude, longitude),
131	    boundary: "fema",
132	    functionName: "fetchFemaCountyByPoint",
133	    errorName: "FemaFetchError",
134	    ...deps,
135	  });
136	  try {
137	    return parseCountyResponse(json);
138	  } catch (cause) {
139	    throw new BoundaryError({
140	      name: "FemaResponseError",
141	      message: `Unexpected FEMA NRI response for point ${latitude},${longitude}: ${cause instanceof Error ? cause.message : "invalid"}`,
142	      functionName: "fetchFemaCountyByPoint",
143	      boundary: "fema",
144	      cause,
145	    });
146	  }
147	}
