1	/**
2	 * @module core/ingest/runIngest
3	 *
4	 * Runs one ingest pass over the active hubs:
5	 *   1. FEMA NRI county record — only for hubs that don't have one yet.
6	 *   2. Open-Meteo daily weather — only the missing days + the last 7 (see planWeatherRange).
7	 * Every step is written to the `events` table under one run id (correlation id).
8	 * One hub failing never stops the others.
9	 *
10	 * All I/O is injected, so this can be tested with fakes and reused by the
11	 * CLI script and the (Step 5) cron route.
12	 */
13	import { randomUUID } from "node:crypto";
14	import { REFETCH_RECENT_DAYS, WEATHER_HISTORY_START } from "../config/ingestConfig";
15	import type { FemaCountyRecord } from "../data/femaNri";
16	import type { ArchiveRequest } from "../data/openMeteo";
17	import type { NewEvent } from "../db/eventsRepository";
18	import type { Hub } from "../domain/hub";
19	import type { DailyWeather } from "../domain/weather";
20	import { describeUnknownError } from "../errors/boundaryError";
21	import { daysInclusive } from "../utils/dates";
22	import { planWeatherRange } from "./planWeatherRange";
23	
24	/** Everything the ingest needs from the outside world. */
25	export interface IngestDeps {
26	  listActiveHubs: () => Promise<Hub[]>;
27	  listHubIdsWithFema: () => Promise<Set<string>>;
28	  fetchFemaCountyByPoint: (latitude: number, longitude: number) => Promise<FemaCountyRecord>;
29	  saveFemaRecord: (hubId: string, record: FemaCountyRecord) => Promise<void>;
30	  getLatestWeatherDate: (hubId: string) => Promise<string | null>;
31	  fetchDailyWeather: (request: ArchiveRequest) => Promise<DailyWeather[]>;
32	  upsertWeatherDays: (hubId: string, days: DailyWeather[]) => Promise<number>;
33	  /** Waits until Open-Meteo allows a request with this many days. */
34	  waitForWeatherQuota: (days: number) => Promise<void>;
35	  recordEvent: (event: NewEvent) => Promise<boolean>;
36	  /** Today's date `YYYY-MM-DD` (UTC). */
37	  today: () => string;
38	  /** Progress output (console in the CLI). */
39	  log: (line: string) => void;
40	}
41	
42	/** Options for one run. */
43	export interface IngestOptions {
44	  /** Limit the run to these hub ids (default: all active hubs). */
45	  hubIds?: string[];
46	  /** Who triggered the run, stored on events. */
47	  trigger: "cli" | "cron";
48	  /** Re-fetch FEMA records even for hubs that already have one (e.g. a new NRI version, or a new field). */
49	  refreshFema?: boolean;
50	}
51	
52	/** What happened to one hub. */
53	export interface HubIngestResult {
54	  hubId: string;
55	  femaFetched: boolean;
56	  weatherRange: { startDate: string; endDate: string } | null;
57	  weatherRowsSaved: number;
58	  error?: string;
59	}
60	
61	/** Summary of a whole run. */
62	export interface IngestSummary {
63	  runId: string;
64	  hubsProcessed: number;
65	  hubsFailed: number;
66	  weatherRowsSaved: number;
67	  femaRecordsSaved: number;
68	  results: HubIngestResult[];
69	}
70	
71	/**
72	 * Ingests FEMA + weather data for one hub.
73	 * @returns what was done.
74	 * @throws whatever the injected I/O throws (caught by the caller).
75	 */
76	async function ingestHub(
77	  hub: Hub,
78	  hasFema: boolean,
79	  runId: string,
80	  deps: IngestDeps,
81	  result: HubIngestResult,
82	): Promise<void> {
83	  if (!hasFema) {
84	    const record = await deps.fetchFemaCountyByPoint(hub.latitude, hub.longitude);
85	    await deps.saveFemaRecord(hub.id, record);
86	    result.femaFetched = true;
87	    await deps.recordEvent({
88	      eventType: "ingest.fema_saved",
89	      source: "ingest",
90	      correlationId: runId,
91	      hubId: hub.id,
92	      message: `${record.countyName} County, ${record.stateCode} (${record.countyFips})`,
93	      payload: { countyFips: record.countyFips, nriVersion: record.nriVersion },
94	    });
95	  }
96	
97	  const range = planWeatherRange({
98	    latestStoredDate: await deps.getLatestWeatherDate(hub.id),
99	    today: deps.today(),
100	    historyStart: WEATHER_HISTORY_START,
101	    refetchRecentDays: REFETCH_RECENT_DAYS,
102	  });
103	  result.weatherRange = range;
104	  if (!range) return;
105	
106	  await deps.waitForWeatherQuota(daysInclusive(range.startDate, range.endDate));
107	  const days = await deps.fetchDailyWeather({
108	    latitude: hub.latitude,
109	    longitude: hub.longitude,
110	    timezone: hub.timezone,
111	    ...range,
112	  });
113	  result.weatherRowsSaved = await deps.upsertWeatherDays(hub.id, days);
114	  await deps.recordEvent({
115	    eventType: "ingest.weather_saved",
116	    source: "ingest",
117	    correlationId: runId,
118	    hubId: hub.id,
119	    message: `${result.weatherRowsSaved} days ${range.startDate}..${range.endDate}`,
120	    payload: { ...range, rows: result.weatherRowsSaved },
121	  });
122	}
123	
124	/**
125	 * Runs one ingest pass.
126	 * @param options - which hubs and who triggered it.
127	 * @param deps - injected I/O.
128	 * @returns the run summary (also stored as the `ingest.finished` event).
129	 * @throws only if the hub list itself can't be read; per-hub failures are recorded and skipped.
130	 */
131	export async function runIngest(options: IngestOptions, deps: IngestDeps): Promise<IngestSummary> {
132	  const runId = randomUUID();
133	  const startedAt = Date.now();
134	  await deps.recordEvent({
135	    eventType: "ingest.started",
136	    source: "ingest",
137	    correlationId: runId,
138	    payload: { trigger: options.trigger, hubIds: options.hubIds ?? "all", refreshFema: options.refreshFema ?? false },
139	  });
140	
141	  const allHubs = await deps.listActiveHubs();
142	  const hubs = options.hubIds ? allHubs.filter((hub) => options.hubIds!.includes(hub.id)) : allHubs;
143	  const unknown = (options.hubIds ?? []).filter((id) => !allHubs.some((hub) => hub.id === id));
144	  if (unknown.length > 0) deps.log(`⚠️  Unknown or inactive hub ids skipped: ${unknown.join(", ")}`);
145	
146	  const withFema = options.refreshFema ? new Set<string>() : await deps.listHubIdsWithFema();
147	  const results: HubIngestResult[] = [];
148	
149	  for (const [index, hub] of hubs.entries()) {
150	    const result: HubIngestResult = { hubId: hub.id, femaFetched: false, weatherRange: null, weatherRowsSaved: 0 };
151	    try {
152	      await ingestHub(hub, withFema.has(hub.id), runId, deps, result);
153	      const range = result.weatherRange ? `${result.weatherRange.startDate}..${result.weatherRange.endDate}` : "up to date";
154	      deps.log(
155	        `[${index + 1}/${hubs.length}] ✅ ${hub.name}: ${result.weatherRowsSaved} days (${range})${result.femaFetched ? " + FEMA" : ""}`,
156	      );
157	    } catch (error) {
158	      result.error = describeUnknownError(error);
159	      deps.log(`[${index + 1}/${hubs.length}] ❌ ${hub.name}: ${result.error}`);
160	      await deps.recordEvent({
161	        eventType: "ingest.hub_failed",
162	        source: "ingest",
163	        level: "error",
164	        correlationId: runId,
165	        hubId: hub.id,
166	        message: result.error,
167	      });
168	    }
169	    results.push(result);
170	  }
171	
172	  const summary: IngestSummary = {
173	    runId,
174	    hubsProcessed: results.length,
175	    hubsFailed: results.filter((r) => r.error).length,
176	    weatherRowsSaved: results.reduce((sum, r) => sum + r.weatherRowsSaved, 0),
177	    femaRecordsSaved: results.filter((r) => r.femaFetched).length,
178	    results,
179	  };
180	  await deps.recordEvent({
181	    eventType: "ingest.finished",
182	    source: "ingest",
183	    level: summary.hubsFailed > 0 ? "warn" : "info",
184	    correlationId: runId,
185	    message: `${summary.hubsProcessed} hubs, ${summary.hubsFailed} failed, ${summary.weatherRowsSaved} weather rows, ${summary.femaRecordsSaved} FEMA records`,
186	    payload: {
187	      durationMs: Date.now() - startedAt,
188	      hubsProcessed: summary.hubsProcessed,
189	      hubsFailed: summary.hubsFailed,
190	      weatherRowsSaved: summary.weatherRowsSaved,
191	      femaRecordsSaved: summary.femaRecordsSaved,
192	      failedHubIds: results.filter((r) => r.error).map((r) => r.hubId),
193	    },
194	  });
195	  return summary;
196	}
