    const secret = "not-a-url-but-secret-looking";
    expect(() => getSupabaseEnv({ SUPABASE_URL: secret })).toThrowError(
      /EnvValidationError \|\| Missing or invalid environment variables: SUPABASE_URL, SUPABASE_SECRET_KEY/,
