 27	  /** The latest saved snapshots of the current scoring version (the alert baseline, D124). */
 28	  getLatestSnapshots: () => Promise<StoredSnapshot[] | null>;
 29	  recordEvent: (event: NewEvent) => Promise<boolean>;
 30	  log: (line: string) => void;
 31	}
 32	
 33	/** Options for one scoring run. */
 34	export interface ScoringOptions {
 35	  trigger: "cli" | "cron" | "ingest";
 36	  /** Reuse the ingest run id so one id covers fetch + score. A new id is made otherwise. */
 37	  runId?: string;
 38	}
 39	
 40	/** What happened to one hub. */
 41	export interface HubScoringResult {
 42	  hubId: string;
 43	  overallScore?: number;
 44	  riskLevel?: RiskLevel;
 45	  confidence?: Confidence;
 46	  /** Non-fatal problem (e.g. unusable FEMA row). */
 47	  warning?: string;
 48	  /** Fatal problem: hub not scored. */
 49	  error?: string;
 50	}
 51	
 52	/** Summary of a scoring run. */
 53	export interface ScoringSummary {
 54	  runId: string;
 55	  scoringVersion: string;
 56	  hubsScored: number;
 57	  hubsFailed: number;
 58	  /** Score-change alerts raised by this run (D124). */
 59	  alerts: number;
 60	  results: HubScoringResult[];
 61	}
 62	
 63	/**
 64	 * The previous run's results for the same scoring version, for the alert comparison.
 65	 * A failure here never stops scoring: alerts are skipped for this run and the problem logged.
 66	 * @param deps - scoring dependencies.
 67	 * @returns results by hub id, or null when unavailable.
 68	 */
 69	async function previousResults(deps: ScoringDeps): Promise<Map<string, { hubId: string; overallScore: number; riskLevel: RiskLevel }> | null> {
 70	  try {
 71	    const snapshots = await deps.getLatestSnapshots();
 72	    if (!snapshots) return null;
 73	    return new Map(snapshots.map((s) => [s.hubId, { hubId: s.hubId, overallScore: s.overallScore, riskLevel: s.riskLevel }]));
 74	  } catch (error) {
 75	    deps.log(
 76	      formatBoundaryMessage({
 77	        name: "AlertBaselineError",
 78	        message: `Could not read the previous scores, so no alerts this run: ${describeUnknownError(error)}`,
 79	        functionName: "runScoring",
 80	        boundary: "database",
 81	      }),
 82	    );
 83	    return null;
 84	  }
 85	}
 86	
 87	/**
 88	 * Scores all active hubs and saves the snapshots.
 89	 * @param options - trigger and optional run id.
 90	 * @param deps - injected I/O.
 91	 * @returns the run summary (also stored as the `scoring.finished` event).
 92	 * @throws only if the hub list, FEMA table or the final save fail; per-hub problems are recorded.
 93	 */
 94	export async function runScoring(options: ScoringOptions, deps: ScoringDeps): Promise<ScoringSummary> {
 95	  const runId = options.runId ?? randomUUID();
 96	  await deps.recordEvent({
 97	    eventType: "scoring.started",
 98	    source: "scoring",
 99	    correlationId: runId,
100	    payload: { trigger: options.trigger, scoringVersion: SCORING_VERSION },
101	  });
102	
103	  const hubs = await deps.listActiveHubs();
104	  const { signals: femaByHub, problems: femaProblems } = await deps.getFemaSignalsByHub();
105	  const previous = await previousResults(deps);
106	  const snapshots: SnapshotToSave[] = [];
107	  const results: HubScoringResult[] = [];
108	
109	  for (const hub of hubs) {
110	    const result: HubScoringResult = { hubId: hub.id, warning: femaProblems.get(hub.id) };
111	    try {
112	      const latest = await deps.getLatestWeatherDate(hub.id);
113	      if (latest === null) throw new Error("no weather data stored yet (run the ingest first)");
114	      const window = scoringWindow(latest);
115	      const observed = computeObservedSignals(await deps.getWeatherDays(hub.id, window.start, window.end), window);
116	      const score = scoreHub(observed, femaByHub.get(hub.id) ?? null);
117	      snapshots.push({ hubId: hub.id, runId, window, score, observedPerYear: observed.perYear, coverage: observed.coverage });
118	      Object.assign(result, { overallScore: score.overallScore, riskLevel: score.riskLevel, confidence: score.confidence });
119	      deps.log(`   ${hub.name.padEnd(16)} ${String(score.overallScore).padStart(5)} ${score.riskLevel.padEnd(6)} top=${score.topHazard} conf=${score.confidence}`);
120	    } catch (error) {
121	      result.error = describeUnknownError(error);
122	      deps.log(`   ❌ ${hub.name}: ${result.error}`);
123	      await deps.recordEvent({
124	        eventType: "scoring.hub_failed",
125	        source: "scoring",
126	        level: "error",
127	        correlationId: runId,
128	        hubId: hub.id,
129	        message: result.error,
130	      });
131	    }
132	    results.push(result);
133	  }
134	
135	  await deps.saveScoreSnapshots(snapshots);
136	
137	  // Score-change alerts (D124): the "if" lives in detectScoreChanges.
138	  const hubName = new Map(hubs.map((hub) => [hub.id, hub.name]));
139	  const alerts = previous
140	    ? detectScoreChanges(
141	        previous,
142	        snapshots.map((s) => ({ hubId: s.hubId, hubName: hubName.get(s.hubId) ?? s.hubId, overallScore: s.score.overallScore, riskLevel: s.score.riskLevel })),
143	      )
144	    : [];
145	  for (const alert of alerts) {
146	    deps.log(`   🔔 ${alert.hubName}: ${alert.fromScore} → ${alert.toScore} (${alert.fromLevel} → ${alert.toLevel})`);
147	    await deps.recordEvent(alertEvent(alert, runId));
148	  }
149	
150	  const summary: ScoringSummary = {
151	    runId,
152	    scoringVersion: SCORING_VERSION,
153	    hubsScored: snapshots.length,
154	    hubsFailed: results.filter((r) => r.error).length,
155	    alerts: alerts.length,
156	    results,
157	  };
158	  const count = (level: RiskLevel) => results.filter((r) => r.riskLevel === level).length;
159	  await deps.recordEvent({
160	    eventType: "scoring.finished",
161	    source: "scoring",
162	    level: summary.hubsFailed > 0 ? "warn" : "info",
163	    correlationId: runId,
164	    message: `${summary.hubsScored} hubs scored (${count("high")} high, ${count("medium")} medium, ${count("low")} low), ${summary.hubsFailed} failed`,
165	    payload: {
166	      scoringVersion: SCORING_VERSION,
167	      hubsScored: summary.hubsScored,
168	      hubsFailed: summary.hubsFailed,
169	      alerts: summary.alerts,
170	      levels: { high: count("high"), medium: count("medium"), low: count("low") },
171	    },
172	  });
173	  return summary;
174	}
