112	/**
113	 * @module core/scoring/observedSignals
114	 *
115	 * Turns daily weather rows into per-year "hazard day" rates for the scoring
116	 * window. Rates use only days that actually have a value:
117	 *   rate = days meeting the threshold × 365.25 ÷ days with data   (D55)
118	 * so a few missing days don't drag a hub's rate down; coverage is reported
119	 * separately and feeds confidence (D51).
120	 */
121	import type { DailyWeather } from "../domain/weather";
122	import { addDays, daysInclusive } from "../utils/dates";
123	import { SCORING_WINDOW_DAYS } from "./config";
124	import { DAY_METRICS, type DayMetricId } from "./dayMetrics";
125	
126	/** A closed date range `YYYY-MM-DD`..`YYYY-MM-DD`. */
127	export interface DateWindow {
128	  start: string;
129	  end: string;
130	}
131	
132	/** Share of expected days that have a value, per weather variable (0..1). */
133	export interface WeatherCoverage {
134	  snowfall: number;
135	  tempMin: number;
136	  precipitation: number;
137	  windGust: number;
138	  apparentTempMax: number;
139	}
140	
141	/** Per-year hazard-day rates (null when no day in the window had data). */
142	export interface PerYearRates {
143	  snowDays: number | null;
144	  /** Reported only, not scored (D50). */
145	  heavySnowDays: number | null;
146	  extremeColdDays: number | null;
147	  heavyRainDays: number | null;
148	  gustAdvisoryDays: number | null;
149	  /** Reported only, not scored (D20a). */
150	  gustWarningDays: number | null;
151	  extremeHeatDays: number | null;
152	}
153	
154	/** Observed-weather inputs for one hub. */
155	export interface ObservedSignals {
156	  window: DateWindow;
157	  expectedDays: number;
158	  coverage: WeatherCoverage;
159	  perYear: PerYearRates;
160	}
