162	/**
163	 * The scoring window: the last {@link SCORING_WINDOW_DAYS} days ending at `latestDate`.
164	 * @param latestDate - newest stored day for the hub.
165	 * @returns the window (both ends included).
166	 */
167	export function scoringWindow(latestDate: string): DateWindow {
168	  return { start: addDays(latestDate, -(SCORING_WINDOW_DAYS - 1)), end: latestDate };
169	}
170	
171	/**
172	 * Counts the days that meet a metric among days that have a value for its variable.
173	 * Shared with the weather-stat tool so both count days identically.
174	 * @param days - the days to look at.
175	 * @param metricId - which hazard-day metric.
176	 * @returns days meeting the threshold and days with data.
177	 */
178	export function countMetricDays(days: DailyWeather[], metricId: DayMetricId): { hits: number; present: number } {
179	  const metric = DAY_METRICS[metricId];
180	  let present = 0;
181	  let hits = 0;
182	  for (const day of days) {
183	    const value = day[metric.variable];
184	    if (value === null) continue;
185	    present++;
186	    if (metric.meets(value)) hits++;
187	  }
188	  return { hits, present };
189	}
190	
191	/**
192	 * Per-year rate of a metric: hits × 365.25 ÷ days with data.
193	 * @returns the rate (null when no data) and how many days had data.
194	 */
195	function ratePerYear(days: DailyWeather[], metricId: DayMetricId): { rate: number | null; present: number } {
196	  const { hits, present } = countMetricDays(days, metricId);
197	  return { rate: present === 0 ? null : (hits * 365.25) / present, present };
198	}
