200	/**
201	 * Computes observed hazard-day rates and coverage for a window.
202	 * @param days - daily rows (rows outside the window are ignored).
203	 * @param window - the scoring window.
204	 * @returns per-year rates and per-variable coverage.
205	 */
206	export function computeObservedSignals(days: DailyWeather[], window: DateWindow): ObservedSignals {
207	  const inWindow = days.filter((day) => day.date >= window.start && day.date <= window.end);
208	  const expectedDays = daysInclusive(window.start, window.end);
209	
210	  const snow = ratePerYear(inWindow, "snow_day");
211	  const heavySnow = ratePerYear(inWindow, "heavy_snow_day");
212	  const cold = ratePerYear(inWindow, "extreme_cold_day");
213	  const rain = ratePerYear(inWindow, "heavy_rain_day");
214	  const gustAdvisory = ratePerYear(inWindow, "gust_advisory_day");
215	  const gustWarning = ratePerYear(inWindow, "gust_warning_day");
216	  const heat = ratePerYear(inWindow, "extreme_heat_day");
217	
218	  const share = (present: number) => (expectedDays === 0 ? 0 : present / expectedDays);
219	  return {
220	    window,
221	    expectedDays,
222	    coverage: {
223	      snowfall: share(snow.present),
224	      tempMin: share(cold.present),
225	      precipitation: share(rain.present),
226	      windGust: share(gustAdvisory.present),
227	      apparentTempMax: share(heat.present),
228	    },
229	    perYear: {
230	      snowDays: snow.rate,
231	      heavySnowDays: heavySnow.rate,
232	      extremeColdDays: cold.rate,
233	      heavyRainDays: rain.rate,
234	      gustAdvisoryDays: gustAdvisory.rate,
235	      gustWarningDays: gustWarning.rate,
236	      extremeHeatDays: heat.rate,
237	    },
238	  };
239	}
