  1	/**
  2	 * @module core/scoring/scoreHub
  3	 *
  4	 * The one entry point for scoring a hub: hazard scores → overall → level →
  5	 * confidence. Pure and deterministic: same inputs, same output, always.
  6	 */
  7	import { SCORING_VERSION } from "./config";
  8	import { weakestConfidence } from "./confidence";
  9	import { computeHazardScores } from "./hazards";
 10	import type { ObservedSignals } from "./observedSignals";
 11	import { computeOverall, riskLevelFor } from "./overall";
 12	import { HAZARDS, type FemaSignals, type Hazard, type HubScore } from "./types";
 13	
 14	/** Rounds to 1 decimal (published precision). */
 15	const round1 = (value: number) => Math.round(value * 10) / 10;
 16	
 17	/**
 18	 * Scores one hub.
 19	 * @param observed - observed-weather signals for the window (null if none).
 20	 * @param fema - FEMA county signals (null if no record).
 21	 * @returns the full, explainable score.
 22	 */
 23	export function scoreHub(observed: ObservedSignals | null, fema: FemaSignals | null): HubScore {
 24	  const hazards = computeHazardScores(observed, fema);
 25	  // The overall is computed from the published (rounded) hazard scores, so the numbers the agent shows add up.
 26	  const scores = Object.fromEntries(HAZARDS.map((h) => [h, hazards[h].score])) as Record<Hazard, number>;
 27	  const overall = computeOverall(scores);
 28	  const overallScore = round1(overall.overallScore);
 29	  return {
 30	    scoringVersion: SCORING_VERSION,
 31	    overallScore,
 32	    weightedAverage: round1(overall.weightedAverage),
 33	    riskLevel: riskLevelFor(overallScore),
 34	    topHazard: overall.topHazard,
 35	    confidence: weakestConfidence(HAZARDS.map((h) => hazards[h].confidence)),
 36	    hazards,
 37	  };
 38	}
 39	/**
 40	 * @module core/scoring/hazards
 41	 *
 42	 * Scores each of the six hazards 0–100 from observed weather and FEMA (D18, D49, D53):
 43	 *
 44	 * | Hazard        | Observed half                     | FEMA half                                   |
 45	 * |---------------|-----------------------------------|---------------------------------------------|
 46	 * | hurricane     | —                                 | hurricane                                   |
 47	 * | winter        | max(snow days, extreme cold days) | max(winter weather, cold wave, ice storm)   |
 48	 * | flood         | heavy rain days                   | max(inland flood per area*, coastal flood) |
 49	 * | severeStorms  | —                                 | avg(tornado per 1,000 sq mi, hail)          |
 50	 * | wind          | gust ≥72 km/h days                | strong wind                                 |
 51	 * | heat          | extreme heat days                 | heat wave                                   |
 52	 *
 53	 * Hazard score = average of the halves that exist.
 54	 * \* per 1,000 sq mi of county, with the area floored at the median US county (D123).
 55	 */
 56	import { FEMA_ANCHORS_P95 as FEMA, INLAND_FLOOD_AREA_FLOOR_SQ_MI, OBSERVED_ANCHORS as OBS } from "./config";
 57	import { femaOnlyConfidence, hybridConfidence, type ConfidenceResult } from "./confidence";
 58	import { linearScore } from "./normalize";
 59	import type { ObservedSignals } from "./observedSignals";
 60	import type { FemaSignals, Hazard, HazardScore, SignalInput } from "./types";
 61	
 62	/**
 63	 * Builds one scored input. Missing observed values stay null; FEMA "not applicable" (null) scores 0 (D18).
 64	 * @returns the input with its score.
 65	 */
 66	function input(
 67	  signal: string,
 68	  source: SignalInput["source"],
 69	  value: number | null,
 70	  unit: string,
 71	  anchor100: number,
 72	  nullMeansZero: boolean,
 73	): SignalInput {
 74	  const effective = value === null && nullMeansZero ? 0 : value;
 75	  return { signal, source, value, unit, anchor100, score: effective === null ? null : linearScore(effective, anchor100) };
 76	}
 77	
 78	/** Max / average of the non-null scores of some inputs (null if none). */
 79	function combine(inputs: SignalInput[], how: "max" | "avg"): number | null {
 80	  const scores = inputs.map((i) => i.score).filter((s): s is number => s !== null);
 81	  if (scores.length === 0) return null;
 82	  return how === "max" ? Math.max(...scores) : scores.reduce((a, b) => a + b, 0) / scores.length;
 83	}
 84	
 85	/** Rounds to 1 decimal (published precision). */
 86	const round1 = (value: number) => Math.round(value * 10) / 10;
 87	
 88	/** How a hazard is built: its two halves and how the sources are cross-checked (D49, D56). */
 89	interface HazardRecipe {
 90	  hazard: Hazard;
 91	  /** Observed-weather inputs (empty for FEMA-only hazards) and how to combine them. */
 92	  observed: { inputs: SignalInput[]; how: "max" | "avg" };
 93	  /** FEMA inputs and how to combine them. */
 94	  fema: { inputs: SignalInput[]; how: "max" | "avg" };
 95	  /**
 96	   * Which FEMA signals the "sources disagree" check compares against observed weather:
 97	   * "all" = every FEMA input, a list = only those (like with like), "none" = halves measure different things.
 98	   */
 99	  crossCheck: "all" | "none" | string[];
100	  /** Share of days with observed data (0..1). */
101	  coverage: number;
102	  hasFemaRecord: boolean;
103	}
104	
105	/**
106	 * Assembles a hazard score from its recipe.
107	 * @param recipe - inputs, combination rules and cross-check settings.
108	 * @returns the rounded hazard score with confidence and inputs.
109	 */
110	function assemble(recipe: HazardRecipe): HazardScore {
111	  const { hazard, observed, fema, crossCheck, coverage, hasFemaRecord } = recipe;
112	  const observedScore = observed.inputs.length > 0 ? combine(observed.inputs, observed.how) : null;
113	  const femaScore = hasFemaRecord ? combine(fema.inputs, fema.how) : null;
114	  const halves = [observedScore, femaScore].filter((s): s is number => s !== null);
115	  const score = halves.length === 0 ? 0 : halves.reduce((a, b) => a + b, 0) / halves.length;
116	
117	  let comparableFemaScore: number | null | "not-comparable" = femaScore;
118	  if (crossCheck === "none") comparableFemaScore = "not-comparable";
119	  else if (Array.isArray(crossCheck) && hasFemaRecord) {
120	    comparableFemaScore = combine(fema.inputs.filter((i) => crossCheck.includes(i.signal)), fema.how);
121	  }
122	
123	  const confidence: ConfidenceResult =
124	    observed.inputs.length === 0
125	      ? femaOnlyConfidence(femaScore)
126	      : hybridConfidence({ observedScore, femaScore, comparableFemaScore, coverage });
127	
128	  return {
129	    hazard,
130	    score: round1(score),
131	    observedScore: observedScore === null ? null : round1(observedScore),
132	    femaScore: femaScore === null ? null : round1(femaScore),
133	    confidence: confidence.confidence,
134	    confidenceReason: confidence.reason,
135	    inputs: [...observed.inputs, ...(hasFemaRecord ? fema.inputs : [])],
136	  };
137	}
