139	/**
140	 * Scores all six hazards for one hub.
141	 * @param observed - observed-weather signals, or null when no weather data exists.
142	 * @param fema - FEMA county signals, or null when no FEMA record exists.
143	 * @returns a score per hazard.
144	 */
145	export function computeHazardScores(observed: ObservedSignals | null, fema: FemaSignals | null): Record<Hazard, HazardScore> {
146	  const o = observed?.perYear;
147	  const cov = observed?.coverage;
148	  const hasFema = fema !== null;
149	  const f = fema ?? ({} as Partial<FemaSignals>);
150	  const days = "days/yr";
151	  const events = "events/yr";
152	  const obs = (signal: keyof typeof OBS, value: number | null | undefined) =>
153	    input(signal, "observed", value ?? null, days, OBS[signal], false);
154	  const fem = (signal: keyof typeof FEMA, value: number | null | undefined, unit = events) =>
155	    input(signal, "fema", value ?? null, unit, FEMA[signal], true);
156	
157	  // Inland flood per 1,000 sq mi, with the area floored at the median US county (D123).
158	  const inlandFloodDensity =
159	    f.inlandFlood === undefined || f.inlandFlood === null || !f.countyAreaSqMi
160	      ? null
161	      : (f.inlandFlood / Math.max(f.countyAreaSqMi, INLAND_FLOOD_AREA_FLOOR_SQ_MI)) * 1_000;
162	  const tornadoDensity =
163	    f.tornado === undefined || f.tornado === null || !f.countyAreaSqMi ? null : (f.tornado / f.countyAreaSqMi) * 1_000;
164	
165	  const none: SignalInput[] = [];
166	  return {
167	    hurricane: assemble({
168	      hazard: "hurricane",
169	      observed: { inputs: none, how: "max" },
170	      fema: { inputs: [fem("hurricane", f.hurricane)], how: "max" },
171	      crossCheck: "all",
172	      coverage: 1,
173	      hasFemaRecord: hasFema,
174	    }),
175	    winter: assemble({
176	      hazard: "winter",
177	      observed: { inputs: [obs("snowDays", o?.snowDays), obs("extremeColdDays", o?.extremeColdDays)], how: "max" },
178	      fema: {
179	        inputs: [
180	          fem("winterWeather", f.winterWeather),
181	          fem("coldWave", f.coldWave, "event-days/yr"),
182	          fem("iceStorm", f.iceStorm, "event-days/yr"),
183	        ],
184	        how: "max",
185	      },
186	      // Ice storms count in the score, but observed weather can't see ice, so they're left out of the cross-check (D56).
187	      crossCheck: ["winterWeather", "coldWave"],
188	      coverage: Math.min(cov?.snowfall ?? 0, cov?.tempMin ?? 0),
189	      hasFemaRecord: hasFema,
190	    }),
191	    flood: assemble({
192	      hazard: "flood",
193	      observed: { inputs: [obs("heavyRainDays", o?.heavyRainDays)], how: "max" },
194	      fema: {
195	        inputs: [fem("inlandFloodPer1000SqMi", inlandFloodDensity, "event-days/yr per 1,000 sq mi"), fem("coastalFlood", f.coastalFlood)],
196	        how: "max",
197	      },
198	      // Heavy-rain days and county-wide flood warnings measure different things (D56).
199	      crossCheck: "none",
200	      coverage: cov?.precipitation ?? 0,
201	      hasFemaRecord: hasFema,
202	    }),
203	    severeStorms: assemble({
204	      hazard: "severeStorms",
205	      observed: { inputs: none, how: "max" },
206	      fema: {
207	        inputs: [fem("tornadoPer1000SqMi", tornadoDensity, "events/yr per 1,000 sq mi"), fem("hail", f.hail)],
208	        how: "avg",
209	      },
210	      crossCheck: "all",
211	      coverage: 1,
212	      hasFemaRecord: hasFema,
213	    }),
214	    wind: assemble({
215	      hazard: "wind",
216	      observed: { inputs: [obs("gustAdvisoryDays", o?.gustAdvisoryDays)], how: "max" },
217	      fema: { inputs: [fem("strongWind", f.strongWind)], how: "max" },
218	      crossCheck: "all",
219	      coverage: cov?.windGust ?? 0,
220	      hasFemaRecord: hasFema,
221	    }),
222	    heat: assemble({
223	      hazard: "heat",
224	      observed: { inputs: [obs("extremeHeatDays", o?.extremeHeatDays)], how: "max" },
225	      fema: { inputs: [fem("heatWave", f.heatWave, "event-days/yr")], how: "max" },
226	      crossCheck: "all",
227	      coverage: cov?.apparentTempMax ?? 0,
228	      hasFemaRecord: hasFema,
229	    }),
230	  };
231	}
232	/**
233	 * @module core/scoring/normalize
234	 *
235	 * Turns a raw rate (days or events per year) into a 0–100 score on a fixed,
236	 * absolute scale: 0 → 0, the anchor → 100, linear in between, capped at 100.
237	 */
238	
239	/**
240	 * Linear 0–100 score with a cap.
241	 * @param value - raw rate, ≥ 0.
242	 * @param anchor100 - the rate that scores 100, > 0.
243	 * @returns score in 0..100 (unrounded).
244	 * @throws Error on a negative/NaN value or a non-positive anchor — bad inputs must never become a quiet number.
245	 */
246	export function linearScore(value: number, anchor100: number): number {
247	  if (!(anchor100 > 0)) throw new Error(`linearScore: anchor must be > 0, got ${anchor100}`);
248	  if (!(value >= 0)) throw new Error(`linearScore: value must be a number ≥ 0, got ${value}`);
249	  return Math.min(100, (value / anchor100) * 100);
250	}
251	/**
252	 * @module core/scoring/overall
253	 *
254	 * Combines the six hazard scores into one overall score (D19):
255	 *   overall = 60% × weighted average + 40% × worst hazard
256	 * so one severe hazard (e.g. Miami hurricanes) is never averaged away.
257	 */
258	import { HAZARD_WEIGHTS, OVERALL_MIX, RISK_LEVEL_CUTOFFS } from "./config";
259	import { HAZARDS, type Hazard, type RiskLevel } from "./types";
260	
261	/** Overall result before rounding/assembly. */
262	export interface OverallResult {
263	  overallScore: number;
264	  weightedAverage: number;
265	  /** Highest-scoring hazard; ties go to the heavier-weighted hazard. */
266	  topHazard: Hazard;
267	}
268	
269	/**
270	 * Computes the overall score from hazard scores.
271	 * @param scores - 0–100 score per hazard.
272	 * @returns overall score, weighted average and top hazard.
273	 */
274	export function computeOverall(scores: Record<Hazard, number>): OverallResult {
275	  const weightedAverage = HAZARDS.reduce((sum, hazard) => sum + HAZARD_WEIGHTS[hazard] * scores[hazard], 0);
276	  // HAZARDS is in weight order, so a strict ">" keeps the heavier hazard on ties.
277	  const topHazard = HAZARDS.reduce((top, hazard) => (scores[hazard] > scores[top] ? hazard : top), HAZARDS[0]);
278	  const overallScore = OVERALL_MIX.weightedAverage * weightedAverage + OVERALL_MIX.worstHazard * scores[topHazard];
279	  return { overallScore, weightedAverage, topHazard };
280	}
281	
282	/**
283	 * Risk level for an overall score, using the score rounded to a whole number:
284	 * Low 0–33, Medium 34–66, High 67–100.
285	 * @param score - 0–100.
286	 * @returns the level.
287	 */
288	export function riskLevelFor(score: number): RiskLevel {
289	  const rounded = Math.round(score);
290	  if (rounded >= RISK_LEVEL_CUTOFFS.highFrom) return "high";
291	  if (rounded >= RISK_LEVEL_CUTOFFS.mediumFrom) return "medium";
292	  return "low";
293	}

  1	/**
  2	 * @module core/scoring/confidence
  3	 *
  4	 * Rule-based confidence (D51), computed in code — never by the LLM.
  5	 * Trust depends on whether data is complete and whether sources AGREE,
  6	 * not on how many sources there are.
  7	 */
  8	import { CONFIDENCE_RULES } from "./config";
  9	import { CONFIDENCE_LEVELS, type Confidence } from "./types";
 10	
 11	/** A confidence level plus a plain-language reason the agent can quote. */
 12	export interface ConfidenceResult {
 13	  confidence: Confidence;
 14	  reason: string;
 15	}
 16	
 17	/**
 18	 * Confidence for a hazard scored from observed weather AND FEMA.
 19	 *
 20	 * The "sources disagree" check compares LIKE WITH LIKE (D56): `comparableFemaScore`
 21	 * is the FEMA score built only from signals observed weather can also see
 22	 * (e.g. winter without ice storms). Pass `"not-comparable"` when the halves
 23	 * measure different things (flood: heavy rain ≠ flood warnings) to skip the check.
 24	 * @param input - the two halves (null = missing), the comparable FEMA score, and observed coverage (0..1).
 25	 * @returns level and reason.
 26	 */
 27	export function hybridConfidence(input: {
 28	  observedScore: number | null;
 29	  femaScore: number | null;
 30	  /** FEMA score for the cross-check; defaults to `femaScore`. */
 31	  comparableFemaScore?: number | null | "not-comparable";
 32	  coverage: number;
 33	}): ConfidenceResult {
 34	  const { observedScore, femaScore, coverage } = input;
 35	  const comparable = input.comparableFemaScore === undefined ? femaScore : input.comparableFemaScore;
 36	  const percentMissing = Math.round((1 - coverage) * 100);
 37	
 38	  if (observedScore === null || femaScore === null) {
 39	    const missing = observedScore === null ? "observed weather" : "FEMA";
 40	    return { confidence: "low", reason: `Only one of two sources is available (${missing} data is missing).` };
 41	  }
 42	  if (coverage < CONFIDENCE_RULES.minimumCoverage) {
 43	    return { confidence: "low", reason: `${percentMissing}% of days in the window have no weather data.` };
 44	  }
 45	  if (coverage < CONFIDENCE_RULES.completeCoverage) {
 46	    return { confidence: "medium", reason: `${percentMissing}% of days in the window have no weather data.` };
 47	  }
 48	  if (comparable === "not-comparable") {
 49	    return {
 50	      confidence: "high",
 51	      reason:
 52	        "Complete data. The two sources measure different things (heavy-rain days vs. county-wide flood warnings), so they are combined but not cross-checked.",
 53	    };
 54	  }
 55	  if (comparable !== null) {
 56	    const gap = Math.abs(observedScore - comparable);
 57	    if (gap > CONFIDENCE_RULES.disagreementPoints) {
 58	      return {
 59	        confidence: "medium",
 60	        reason: `The two sources disagree: observed weather scores ${Math.round(observedScore)}, FEMA's long-term county record scores ${Math.round(comparable)} on the same phenomenon.`,
 61	      };
 62	    }
 63	  }
 64	  return { confidence: "high", reason: "Complete data, and observed weather and FEMA's record tell the same story." };
 65	}
 66	
 67	/**
 68	 * Confidence for a hazard scored from FEMA only (hurricane, severe storms):
 69	 * FEMA's long historical record is the right source for rare events.
 70	 * @param femaScore - the FEMA score, or null when the record is missing.
 71	 * @returns level and reason.
 72	 */
 73	export function femaOnlyConfidence(femaScore: number | null): ConfidenceResult {
 74	  if (femaScore === null) return { confidence: "low", reason: "No FEMA record is available for this hub's county." };
 75	  return { confidence: "high", reason: "Based on FEMA's long-term county frequency record (rare events need decades of data)." };
 76	}
 77	
 78	/**
 79	 * The weakest of several confidence levels.
 80	 * @param levels - at least one level.
 81	 * @returns the lowest one.
 82	 * @throws Error on an empty list.
 83	 */
 84	export function weakestConfidence(levels: Confidence[]): Confidence {
 85	  if (levels.length === 0) throw new Error("weakestConfidence needs at least one level");
 86	  return levels.reduce((weakest, level) =>
 87	    CONFIDENCE_LEVELS.indexOf(level) > CONFIDENCE_LEVELS.indexOf(weakest) ? level : weakest,
 88	  );
 89	}
 90	/**
 91	 * @module core/scoring/caveats
 92	 *
 93	 * Standing caveats (G4): honest limits of our data, stated plainly (D20b).
 94	 * Tools attach them, and the answer validator guarantees the ones for every
 95	 * hazard/metric used end up in the answer's `limitations` — the LLM can add
 96	 * caveats but never drop these. Thresholds are built from config, never retyped.
 97	 */
 98	import { formatDual, type UnitSystem } from "../utils/units";
 99	import { DAY_METRICS, type DayMetric, type DayMetricId } from "./dayMetrics";
100	import type { Hazard } from "./types";
101	
102	/** Caveats that apply to every score answer. */
103	export const GENERAL_CAVEATS: readonly string[] = [
104	  "Scores measure exposure (how often hazardous weather hits a hub's location), not dollar losses. Hub volume, building condition and existing resilience upgrades are not included.",
105	  "Each hub is its metro's city-center point: weather comes from a ~10 km model grid cell, FEMA data from the county containing that point.",
106	];
107	
108	/** Caveat for anything built on observed weather. */
109	export const WEATHER_DATA_CAVEAT =
110	  "Observed weather is modeled reanalysis (Open-Meteo), not station measurements, so it smooths out extremes.";
111	
112	/**
113	 * Standing caveats for one hazard.
114	 * @param hazard - the hazard.
115	 * @param units - which unit system leads in the text.
116	 * @returns plain-language caveats.
117	 */
118	export function hazardCaveats(hazard: Hazard, units: UnitSystem): string[] {
119	  const t = (id: DayMetricId) => formatDual(DAY_METRICS[id].threshold, units);
120	  switch (hazard) {
121	    case "hurricane":
122	      return ["Hurricane exposure comes from FEMA's long-term county frequency; any single season can be far above or below it."];
123	    case "winter":
124	      return [
125	        `Heavy-snow days, ${t("heavy_snow_day")}, are barely registered by modeled data, so they are reported but not scored.`,
126	        "Ice storms come from FEMA only — observed weather has no ice signal.",
127	        "Local adaptation is not modeled: the same snow disrupts southern cities more than northern ones.",
128	      ];
129	    case "flood":
130	      return [
131	        `Heavy-rain days, ${t("heavy_rain_day")}, are not the same as flooding. FEMA's inland flood frequency counts flood warnings anywhere in the county, so it is divided by the county's area (never less than a typical county's), which keeps very large counties from looking overstated. Large counties that are urban throughout can be understated instead.`,
132	        "In very large counties (e.g. Phoenix, Las Vegas, Los Angeles) FEMA's flood frequency is likely overstated, and for many big metros it is at the top of the scale.",
133	      ];
134	    case "severeStorms":
135	      return [
136	        "Severe storms (tornado + hail) come from FEMA only — five years of daily weather cannot measure them.",
137	        "Tornado frequency is scored per county area, because FEMA spreads tornado frequency by area.",
138	      ];
139	    case "wind":
140	      return [
141	        `Warning-level gusts, ${t("gust_warning_day")}, are undercounted by modeled data, so wind is scored on advisory-level gust days, ${t("gust_advisory_day")}.`,
142	      ];
143	    case "heat":
144	      return [
145	        `Observed heat uses one national threshold, ${t("extreme_heat_day")}; FEMA heat waves follow local heat-alert criteria, so the two can differ.`,
146	      ];
147	  }
148	}
149	
150	/**
151	 * Standing caveats for one weather-stat metric.
152	 * @param metricId - the metric.
153	 * @param units - which unit system leads in the text.
154	 * @returns plain-language caveats (always includes the reanalysis caveat).
155	 */
156	export function metricCaveats(metricId: DayMetricId, units: UnitSystem): string[] {
157	  const caveats = [WEATHER_DATA_CAVEAT];
158	  const metric: DayMetric = DAY_METRICS[metricId];
159	  if (!metric.scored && metric.notScoredBecause) {
160	    caveats.push(`The ${metric.label} count, ${formatDual(metric.threshold, units)}, is reported only: ${metric.notScoredBecause}.`);
161	  }
162	  return caveats;
163	}
164	/**
165	 * @module core/scoring/ranking
166	 *
167	 * Ranks are DERIVED when read, never stored (D54), so they can't go stale when
168	 * hubs are added. Rank 1 = most exposed. Ties share a rank ("1, 2, 2, 4").
169	 */
170	import type { CensusRegion } from "../domain/hub";
171	import type { Hazard } from "./types";
172	
173	/** What to rank by: the overall score or one hazard. */
174	export type RankMetric = "overall" | Hazard;
175	
176	/** The minimum a row needs to be ranked. */
177	export interface RankableRow {
178	  hubId: string;
179	  region: CensusRegion;
180	  scores: Partial<Record<RankMetric, number>> & { overall: number };
181	}
182	
183	/** One ranked row. */
184	export interface RankedRow {
185	  hubId: string;
186	  score: number;
187	  /** Rank among all hubs (1 = most exposed). */
188	  rankAmongAll: number;
189	  totalHubs: number;
190	  /** Rank within the filtered selection (e.g. within the Midwest). */
191	  rankInSelection: number;
192	  selectionSize: number;
193	}
194	
195	/**
196	 * Standard competition ranking on score, highest first.
197	 * @param items - ids with scores.
198	 * @returns id → rank.
199	 */
200	export function competitionRanks(items: { id: string; score: number }[]): Map<string, number> {
201	  const sorted = [...items].sort((a, b) => b.score - a.score);
202	  const ranks = new Map<string, number>();
203	  sorted.forEach((item, index) => {
204	    const previous = sorted[index - 1];
205	    ranks.set(item.id, previous && previous.score === item.score ? ranks.get(previous.id)! : index + 1);
206	  });
207	  return ranks;
208	}
209	
210	/**
211	 * Ranks hubs by a metric, optionally within a region.
212	 * @param rows - every hub's scores (the full set, so "rank among all" is correct).
213	 * @param options - metric, optional region filter, order and limit.
214	 * @returns the requested slice, most or least exposed first.
215	 */
216	export function rankHubs(
217	  rows: RankableRow[],
218	  options: { metric: RankMetric; region?: CensusRegion; order: "most" | "least"; limit: number },
219	): RankedRow[] {
220	  const scoreOf = (row: RankableRow) => row.scores[options.metric] ?? 0;
221	  const allRanks = competitionRanks(rows.map((row) => ({ id: row.hubId, score: scoreOf(row) })));
222	  const selection = options.region ? rows.filter((row) => row.region === options.region) : rows;
223	  const selectionRanks = competitionRanks(selection.map((row) => ({ id: row.hubId, score: scoreOf(row) })));
224	
225	  const ranked = selection
226	    .map((row) => ({
227	      hubId: row.hubId,
228	      score: scoreOf(row),
229	      rankAmongAll: allRanks.get(row.hubId)!,
230	      totalHubs: rows.length,
231	      rankInSelection: selectionRanks.get(row.hubId)!,
232	      selectionSize: selection.length,
233	    }))
234	    .sort((a, b) => (options.order === "most" ? b.score - a.score : a.score - b.score));
235	  return ranked.slice(0, options.limit);
236	}
237	
238	/** Who is highest/lowest among some hubs and how many points apart they are. */
239	export interface ScoreSpread {
240	  highestHubId: string;
241	  lowestHubId: string;
242	  /** highest − lowest, rounded to 1 decimal. */
243	  spread: number;
244	}
245	
246	/**
247	 * Gap between the highest and lowest score (E10): computed in code so the agent
248	 * can quote "4.3 points apart" without doing arithmetic itself.
249	 * @param entries - hub ids with scores.
250	 * @returns the spread, or null for fewer than two entries.
251	 */
252	export function scoreSpread(entries: { hubId: string; score: number }[]): ScoreSpread | null {
253	  if (entries.length < 2) return null;
254	  const sorted = [...entries].sort((a, b) => b.score - a.score);
255	  const highest = sorted[0];
256	  const lowest = sorted[sorted.length - 1];
257	  return { highestHubId: highest.hubId, lowestHubId: lowest.hubId, spread: Math.round((highest.score - lowest.score) * 10) / 10 };
258	}

  1	/**
  2	 * @module core/widgets/widgetsData
  3	 *
  4	 * Data for the dashboard widgets (A5) — computed in code from the latest
  5	 * snapshots, no LLM involved: top hubs, the leader per hazard, data freshness.
  6	 */
  7	import type { StoredSnapshot } from "../db/scoresRepository";
  8	import type { Hub } from "../domain/hub";
  9	import { FEMA_ANCHORS_NRI_VERSION } from "../scoring/config";
 10	import { riskLevelFor } from "../scoring/overall";
 11	import { competitionRanks } from "../scoring/ranking";
 12	import { HAZARDS, type Confidence, type Hazard, type RiskLevel } from "../scoring/types";
 13	import type { DataBounds } from "../stats/weatherStats";
 14	
 15	/** Inputs for the widgets. */
 16	export interface WidgetsInput {
 17	  hubs: Hub[];
 18	  snapshots: StoredSnapshot[];
 19	  weatherBounds: DataBounds;
 20	}
 21	
 22	/** Everything the widget column shows. */
 23	export interface WidgetsData {
 24	  topHubs: {
 25	    hubId: string;
 26	    hub: string;
 27	    rank: number;
 28	    score: number;
 29	    level: RiskLevel;
 30	    topHazard: Hazard;
 31	    confidence: Confidence;
 32	  }[];
 33	  hazardLeaders: { hazard: Hazard; hubId: string; hub: string; score: number; level: RiskLevel }[];
 34	  dataStatus: {
 35	    weatherFrom: string;
 36	    weatherThrough: string;
 37	    hubCount: number;
 38	    scoredAt: string;
 39	    scoringVersion: string;
 40	    scoringWindow: { start: string; end: string };
 41	    femaVersion: string;
 42	  };
 43	}
 44	
 45	/** How many hubs the "top hubs" widget shows. */
 46	export const TOP_HUBS_COUNT = 5;
 47	
 48	/**
 49	 * Builds the widget data.
 50	 * @param input - active hubs, latest snapshots and weather date range.
 51	 * @returns top hubs, hazard leaders and data status.
 52	 * @throws Error when there are no snapshots.
 53	 */
 54	export function buildWidgetsData({ hubs, snapshots, weatherBounds }: WidgetsInput): WidgetsData {
 55	  if (snapshots.length === 0) throw new Error("No snapshots to build widgets from.");
 56	  const hubById = new Map(hubs.map((h) => [h.id, h]));
 57	  const active = snapshots.filter((s) => hubById.has(s.hubId));
 58	  const label = (hubId: string) => `${hubById.get(hubId)!.name}, ${hubById.get(hubId)!.state}`;
 59	  const ranks = competitionRanks(active.map((s) => ({ id: s.hubId, score: s.overallScore })));
 60	
 61	  const topHubs = [...active]
 62	    .sort((a, b) => b.overallScore - a.overallScore)
 63	    .slice(0, TOP_HUBS_COUNT)
 64	    .map((s) => ({
 65	      hubId: s.hubId,
 66	      hub: label(s.hubId),
 67	      rank: ranks.get(s.hubId)!,
 68	      score: s.overallScore,
 69	      level: s.riskLevel,
 70	      topHazard: s.topHazard,
 71	      confidence: s.confidence,
 72	    }));
 73	
 74	  const hazardLeaders = HAZARDS.map((hazard) => {
 75	    const leader = active.reduce((best, s) => (s.hazards[hazard].score > best.hazards[hazard].score ? s : best));
 76	    const score = leader.hazards[hazard].score;
 77	    return { hazard, hubId: leader.hubId, hub: label(leader.hubId), score, level: riskLevelFor(score) };
 78	  });
 79	
 80	  const newest = active.reduce((a, b) => (a.createdAt > b.createdAt ? a : b));
 81	  return {
 82	    topHubs,
 83	    hazardLeaders,
 84	    dataStatus: {
 85	      weatherFrom: weatherBounds.earliest,
 86	      weatherThrough: weatherBounds.latest,
 87	      hubCount: active.length,
 88	      scoredAt: newest.createdAt,
 89	      scoringVersion: newest.scoringVersion,
 90	      scoringWindow: newest.window,
 91	      femaVersion: `FEMA National Risk Index (${FEMA_ANCHORS_NRI_VERSION})`,
 92	    },
 93	  };
 94	}
 95	/**
 96	 * @module core/widgets/loadWidgetsData
 97	 *
 98	 * Loads what the widgets need from the database and builds their data.
 99	 */
100	import { listActiveHubs } from "../db/hubsRepository";
101	import { getLatestSnapshots } from "../db/scoresRepository";
102	import { getWeatherBounds } from "../db/weatherRepository";
103	import { BoundaryError } from "../errors/boundaryError";
104	import { buildWidgetsData, type WidgetsData } from "./widgetsData";
105	
106	/**
107	 * Reads hubs, latest snapshots and the weather date range, then builds the widget data.
108	 * @returns the widget data.
109	 * @throws BoundaryError (database) — `NoDataError` when nothing has been scored yet.
110	 */
111	export async function loadWidgetsData(): Promise<WidgetsData> {
112	  const [hubs, snapshots, weatherBounds] = await Promise.all([listActiveHubs(), getLatestSnapshots(), getWeatherBounds()]);
113	  if (!snapshots || snapshots.length === 0 || !weatherBounds) {
114	    throw new BoundaryError({
115	      name: "NoDataError",
116	      message: "No scores yet — run `npm run ingest` first",
117	      functionName: "loadWidgetsData",
118	      boundary: "database",
119	    });
120	  }
121	  return buildWidgetsData({ hubs, snapshots, weatherBounds });
122	}

  1	/**
  2	 * @module core/stats/weatherStats
  3	 *
  4	 * Pure functions behind the `get_weather_stat` tool: turn a requested period
  5	 * into exact dates (clipped to the data we have, with notes), and count
  6	 * hazard days in it. Percentages are of days WITH data, and coverage is
  7	 * reported so the agent can be honest about gaps.
  8	 */
  9	import type { DailyWeather } from "../domain/weather";
 10	import { countMetricDays, type DateWindow } from "../scoring/observedSignals";
 11	import type { DayMetricId } from "../scoring/dayMetrics";
 12	import { addDays, daysInclusive } from "../utils/dates";
 13	
 14	/** A period as the tool receives it. `month` (1–12) narrows a year. */
 15	export type PeriodRequest =
 16	  | { kind: "year"; year: number; month?: number }
 17	  | { kind: "range"; startDate: string; endDate: string }
 18	  | { kind: "last12Months" };
 19	
 20	/** A resolved period: exact dates, a human label, and notes about clipping. */
 21	export interface ResolvedPeriod extends DateWindow {
 22	  label: string;
 23	  notes: string[];
 24	}
 25	
 26	/** The range of dates we have data for. */
 27	export interface DataBounds {
 28	  earliest: string;
 29	  latest: string;
 30	}
 31	
 32	const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
 33	
 34	/** @returns the last day of a month, `YYYY-MM-DD`. */
 35	function lastDayOfMonth(year: number, month: number): string {
 36	  return addDays(`${month === 12 ? year + 1 : year}-${String(month === 12 ? 1 : month + 1).padStart(2, "0")}-01`, -1);
 37	}
 38	
 39	/**
 40	 * Resolves a requested period to exact dates within the available data.
 41	 * @param request - year (optionally a month), date range, or last 12 months.
 42	 * @param bounds - earliest and latest stored day.
 43	 * @returns the dates, a label and notes (e.g. "2026 is incomplete").
 44	 * @throws Error with a user-readable message when the period has no data or is malformed.
 45	 */
 46	export function resolvePeriod(request: PeriodRequest, bounds: DataBounds): ResolvedPeriod {
 47	  let start: string;
 48	  let end: string;
 49	  let label: string;
 50	
 51	  if (request.kind === "last12Months") {
 52	    end = bounds.latest;
 53	    start = addDays(end, -364);
 54	    label = `the last 12 months (${start} to ${end})`;
 55	  } else if (request.kind === "year") {
 56	    const { year, month } = request;
 57	    if (month !== undefined && (month < 1 || month > 12)) throw new Error(`Month must be 1–12, got ${month}.`);
 58	    start = month ? `${year}-${String(month).padStart(2, "0")}-01` : `${year}-01-01`;
 59	    end = month ? lastDayOfMonth(year, month) : `${year}-12-31`;
 60	    label = month ? `${MONTHS[month - 1]} ${year}` : `calendar year ${year}`;
 61	  } else {
 62	    start = request.startDate;
 63	    end = request.endDate;
 64	    if (daysInclusive(start, end) === 0) throw new Error(`The end date ${end} is before the start date ${start}.`);
 65	    label = `${start} to ${end}`;
 66	  }
 67	
 68	  if (end < bounds.earliest || start > bounds.latest) {
 69	    throw new Error(`No weather data for ${label}: our data starts ${bounds.earliest} and ends ${bounds.latest}.`);
 70	  }
 71	
 72	  const notes: string[] = [];
 73	  if (start < bounds.earliest) {
 74	    notes.push(`Our data starts ${bounds.earliest}, so the period was shortened to begin then.`);
 75	    start = bounds.earliest;
 76	  }
 77	  if (end > bounds.latest) {
 78	    notes.push(`The period is incomplete: data runs through ${bounds.latest}.`);
 79	    end = bounds.latest;
 80	  }
 81	  return { start, end, label, notes };
 82	}
 83	
 84	/** Result of counting one metric over a period. */
 85	export interface WeatherStat {
 86	  daysMeeting: number;
 87	  daysWithData: number;
 88	  daysInPeriod: number;
 89	  /** daysMeeting ÷ daysWithData × 100, 1 decimal (null when no data). */
 90	  percentOfDays: number | null;
 91	  /** daysWithData ÷ daysInPeriod (0..1). */
 92	  coverage: number;
 93	}
 94	
 95	/**
 96	 * Counts days meeting a metric in a period.
 97	 * @param days - daily rows (rows outside the period are ignored).
 98	 * @param metricId - which hazard-day metric.
 99	 * @param period - the exact dates.
100	 * @returns counts, percentage and coverage.
101	 */
102	export function computeWeatherStat(days: DailyWeather[], metricId: DayMetricId, period: DateWindow): WeatherStat {
103	  const inPeriod = days.filter((day) => day.date >= period.start && day.date <= period.end);
104	  const { hits, present } = countMetricDays(inPeriod, metricId);
105	  const daysInPeriod = daysInclusive(period.start, period.end);
106	  return {
107	    daysMeeting: hits,
108	    daysWithData: present,
109	    daysInPeriod,
110	    percentOfDays: present === 0 ? null : Math.round((hits / present) * 1000) / 10,
111	    coverage: daysInPeriod === 0 ? 0 : Math.round((present / daysInPeriod) * 1000) / 1000,
112	  };
113	}
114	
115	/** Hazard days in one calendar month. */
116	export interface MonthlyCount {
117	  /** `YYYY-MM`. */
118	  month: string;
119	  /** e.g. "Jan 2025". */
120	  label: string;
121	  daysMeeting: number;
122	  daysWithData: number;
123	}
124	
125	/**
126	 * Counts metric days per calendar month across a period (every month in the
127	 * period is listed, even with no data), for the seasonality strip.
128	 * @param days - daily rows (rows outside the period are ignored).
129	 * @param metricId - which hazard-day metric.
130	 * @param period - the exact dates.
131	 * @returns one entry per month, oldest first.
132	 */
133	export function computeMonthlyCounts(days: DailyWeather[], metricId: DayMetricId, period: DateWindow): MonthlyCount[] {
134	  const months: MonthlyCount[] = [];
135	  let cursor = `${period.start.slice(0, 7)}-01`;
136	  while (cursor <= period.end) {
137	    const month = cursor.slice(0, 7);
138	    const inMonth = days.filter((d) => d.date.startsWith(month) && d.date >= period.start && d.date <= period.end);
139	    const { hits, present } = countMetricDays(inMonth, metricId);
140	    months.push({ month, label: `${MONTHS[Number(month.slice(5)) - 1].slice(0, 3)} ${month.slice(0, 4)}`, daysMeeting: hits, daysWithData: present });
141	    cursor = addDays(lastDayOfMonth(Number(month.slice(0, 4)), Number(month.slice(5))), 1);
142	  }
143	  return months;
