308	    hubName: hubName(top.hubId),
309	    fromScore,
310	    toScore: top.overallScore,
311	    change: Math.round((top.overallScore - fromScore) * 10) / 10,
312	    fromLevel: riskLevelFor(fromScore),
313	    toLevel: top.riskLevel,
314	    test: true,
315	  };
316	  return alertEvent(alert, randomUUID()); // correlation_id is a uuid column; the payload marks it as a test
